import { BoxPlot, useBoxPlot } from '@dreadnought/ui/react';
const data = [{id:'a',label:'Группа A',values:[1,2,3,4,5,6,7,100,100]}];
function Summary() { const {layout,page} = useBoxPlot(); return <button onClick={() => page.change(2)}>Страница {page.page}, групп {layout.groups.length}</button>; }
export function Example() { return <BoxPlot label="Распределение" data={data} pageSize={1}><Summary /><BoxPlot.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</BoxPlot.Plot><BoxPlot.Axis /><BoxPlot.Table /><BoxPlot.Pagination /><BoxPlot.Empty /></BoxPlot>; }
